<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\BelongsToMany;
use Illuminate\Database\Eloquent\Relations\HasMany;
class AemsRiskMatrixItem extends Model { use HasFactory; protected $fillable = ['risk_matrix_id','risk_code','risk_statement','risk_category','inherent_likelihood','inherent_impact','inherent_score','control_description','control_effectiveness','residual_likelihood','residual_impact','residual_score','residual_rating','risk_response','responsible_office_id','sequence','status','audit_area_id','audit_focus_id','process_flow_id','process_name','risk_area','planned_audit_approach','criteria','response_rationale','source_reference']; protected function casts(): array { return ['inherent_likelihood'=>'decimal:2','inherent_impact'=>'decimal:2','inherent_score'=>'decimal:2','residual_likelihood'=>'decimal:2','residual_impact'=>'decimal:2','residual_score'=>'decimal:2']; } public function matrix(): BelongsTo { return $this->belongsTo(AemsRiskMatrix::class,'risk_matrix_id'); } public function responsibleOffice(): BelongsTo { return $this->belongsTo(Office::class,'responsible_office_id')->withTrashed(); } public function auditArea(): BelongsTo { return $this->belongsTo(AuditArea::class,'audit_area_id')->withTrashed(); } public function auditFocus(): BelongsTo { return $this->belongsTo(AuditFocus::class,'audit_focus_id')->withTrashed(); } public function processFlow(): BelongsTo { return $this->belongsTo(AemsProcessFlowDocument::class,'process_flow_id'); } public function objectives(): BelongsToMany { return $this->belongsToMany(AemsPlanningObjective::class,'aems_risk_objective_links','risk_matrix_item_id','planning_objective_id')->withPivot('relationship_basis')->withTimestamps(); } public function procedures(): BelongsToMany { return $this->belongsToMany(AuditProgramProcedure::class,'aems_risk_procedure_links','risk_matrix_item_id','audit_program_procedure_id')->withPivot('relationship_basis')->withTimestamps(); } public function workingPaperLinks(): HasMany { return $this->hasMany(AemsRiskWorkingPaperLink::class,'risk_matrix_item_id'); } }
